test('PER AI OPS readability overrides are limited to source cards and retain source text with high contrast',()=>{
 const p=page(async()=>{throw Error('No request expected');}),values=new Map(),styleFor=n=>({setProperty:(k,v,priority)=>values.set(n+':'+k,{value:v,priority})}),host=p.host,card=new Node('div'),span=new Node('span'),warn=new Node('div'),title=new Node('div'),outside=new Node('div');host.style=styleFor('host');card.style=styleFor('card');span.style=styleFor('span');warn.style=styleFor('warn');title.style=styleFor('title');outside.style=styleFor('outside');card.textContent='Read source unavailable';card.querySelectorAll=()=>[span];warn.querySelectorAll=()=>[];warn.classList={contains:n=>n==='mmd-aiops-warn'};host.querySelectorAll=q=>q==='.mmd-aiops-k'?[title]:q.includes('.mmd-aiops-item')?[card,warn]:[];const header=new Node('small');header.tagName='SMALL';header.style=styleFor('header');p.document.querySelectorAll=()=>[header];p.refresh();assert.equal(values.get('header:color').value,'#ffffff');assert.equal(values.get('header:font-size').value,'14px');assert.equal(card.textContent,'Read source unavailable');assert.deepEqual(values.get('card:background'),{value:'#ffffff',priority:'important'});assert.equal(values.get('span:color').value,'#202936');assert.equal(values.get('card:font-size').value,'16px');assert.equal(values.get('warn:color').value,'#744210');assert.equal(values.get('title:color').value,'#704815');assert.equal([...values.keys()].some(k=>k.startsWith('outside:')),false);
 const luminance=hex=>{const c=hex.match(/[a-f0-9]{2}/gi).map(x=>parseInt(x,16)/255).map(x=>x<=.04045?x/12.92:((x+.055)/1.055)**2.4);return c[0]*.2126+c[1]*.7152+c[2]*.0722;};for(const [fg,bg] of [['#202936','#ffffff'],['#744210','#fff7ed'],['#704815','#ffffff']])assert.ok((Math.max(luminance(fg),luminance(bg))+.05)/(Math.min(luminance(fg),luminance(bg))+.05)>=4.5);
});
